import ipaddress

NEVER_BLOCK = [ipaddress.ip_network(n) for n in
               ("10.0.0.0/8", "192.0.2.53/32")]   # internal, our resolver

class BlockGuard:
    def __init__(self, firewall, max_per_hour=20, dry_run=True):
        self.firewall, self.max = firewall, max_per_hour
        self.dry_run, self.done = dry_run, []

    def block(self, ip_text, reason):
        ip = ipaddress.ip_address(ip_text)            # ValueError if junk
        ip_text = str(ip)                  # one spelling per address
        if any(ip in net for net in NEVER_BLOCK):
            return "refused: on the never-block list"
        if ip_text in self.done:
            return "no-op: already blocked"           # idempotent
        if len(self.done) >= self.max:
            return "refused: hourly cap reached, page a human"
        if self.dry_run:
            self.done.append(ip_text)
            return f"dry run: would block {ip_text} ({reason})"
        self.firewall.add(ip_text)
        self.done.append(ip_text)
        return f"blocked {ip_text}"

import pytest
from guard import BlockGuard

class FakeFirewall:
    def __init__(self):
        self.rules = []
    def add(self, ip):
        self.rules.append(ip)

def test_block_twice_adds_one_rule():
    fw = FakeFirewall()
    g = BlockGuard(fw, dry_run=False)
    g.block("203.0.113.7", "spray")
    assert g.block("203.0.113.7", "spray") == "no-op: already blocked"
    assert fw.rules == ["203.0.113.7"]

def test_never_blocks_our_resolver():
    g = BlockGuard(FakeFirewall(), dry_run=False)
    assert g.block("192.0.2.53", "spray").startswith("refused")

def test_cap_stops_a_flood():
    g = BlockGuard(FakeFirewall(), max_per_hour=2, dry_run=False)
    for i in range(1, 3):
        g.block(f"198.51.100.{i}", "spray")
    assert "cap reached" in g.block("198.51.100.3", "spray")

def test_dry_run_touches_nothing():
    fw = FakeFirewall()
    assert BlockGuard(fw).block("203.0.113.7", "spray").startswith("dry run")
    assert fw.rules == []

def test_rejects_text_that_is_not_an_ip():
    with pytest.raises(ValueError):
        BlockGuard(FakeFirewall()).block("203.0.113.7; drop", "spray")

import json

ALLOWED = ("likely_benign", "needs_review", "likely_malicious")
MISSING = object()   # unlike None, equals nothing

def lookup(node, path):
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return MISSING
        node = node[part]
    return node

def check(alert, text):
    try:
        reply = json.loads(text)
    except json.JSONDecodeError:
        return "rejected: not JSON"
    if not isinstance(reply, dict) or reply.get("suggestion") not in ALLOWED:
        return "rejected: suggestion outside the allowed set"
    evidence = reply.get("evidence")
    if not isinstance(evidence, list) or not evidence:
        return "rejected: no evidence cited"
    for ev in evidence:
        ev = ev if isinstance(ev, dict) else {}
        have = lookup(alert, str(ev.get("field")))
        if have is MISSING or have != ev.get("value", MISSING):
            return f"rejected: evidence {ev.get('field')}={ev.get('value')!r} not in alert"
    return "accepted as advice: " + reply["suggestion"]

